import json
def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0]); seen=set()
    for r in range(H):
        for c in range(W):
            col=g[r][c]
            if col==0 and g==g: pass
            # find box: top-left of a solid rectangle of col with border
            # detect rectangle: extend right and down while same color
            if (r,c) in seen: continue
            w=0
            while c+w<W and g[r][c+w]==col: w+=1
            h=0
            while r+h<H and all(g[r+h][c+x]==col for x in range(w)): h+=1
            if w>=3 and h>=3 and (w< W or True):
                # require it's a full rectangle outline (border all col, interior bg)
                interior=[row[c+1:c+w-1] for row in g[r+1:r+h-1]]
                if all(x!=col for row in interior for x in row):
                    fill = h-1 if (h-1==w-1 and (h-1)%2==0) else 7
                    for i in range(r+1,r+h-1):
                        for j in range(c+1,c+w-1):
                            g[i][j]=fill
                for i in range(r,r+h):
                    for j in range(c,c+w): seen.add((i,j))
    return g
