            if seen[i][j] or g[i][j]==bg: continue
            col=g[i][j]; q=deque([(i,j)]); seen[i][j]=True; cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<H and 0<=b<W and not seen[a][b] and g[a][b]==col:
                        seen[a][b]=True; q.append((a,b))
            r0=min(y for y,x in cells); r1=max(y for y,x in cells)
            c0=min(x for y,x in cells); c1=max(x for y,x in cells)
            h,w=r1-r0+1,c1-c0+1
            if h<3 or w<3: continue
            fill=2 if h-2==w-2==2 else 7
            for a in range(r0,r1+1):
                for b in range(c0,c1+1):
                    if g[a][b]!=col: g[a][b]=fill
    return g
